<script setup>import AppShell from'../../Layouts/AppShell.vue';import{Head,useForm}from'@inertiajs/vue3';const form=useForm({name:'',event_type:'wedding',privacy:'private',location:'',membership_limit:500,access_options:['partial_access','full_access'],face_recognition_enabled:true,allow_guest_upload:false,watermark_enabled:false});</script><template><AppShell><Head title="Create event"/><div class="mx-auto max-w-3xl"><p class="eyebrow">New event</p><h1 class="mt-2 font-display text-3xl font-bold">Set the stage</h1><form class="panel mt-8 space-y-5 p-6 md:p-8" @submit.prevent="form.post('/groups')"><label class="block text-sm font-semibold">Event name<input v-model="form.name" class="field mt-2" placeholder="Aarav & Mira — Mumbai" required></label><div class="grid gap-5 md:grid-cols-2"><label class="text-sm font-semibold">Event type<select v-model="form.event_type" class="field mt-2"><option value="wedding">Wedding</option><option value="corporate">Corporate</option><option value="sports">Sports</option><option value="other">Other</option></select></label><label class="text-sm font-semibold">Privacy<select v-model="form.privacy" class="field mt-2"><option value="private">Private</option><option value="link_only">Invitation only</option><option value="public">Public</option></select></label></div><label class="block text-sm font-semibold">Location<input v-model="form.location" class="field mt-2" placeholder="Mumbai, Maharashtra"></label><div class="grid gap-3 rounded-xl bg-black/[.03] p-4 text-sm"><label class="flex gap-3"><input v-model="form.face_recognition_enabled" type="checkbox">Enable consent-led My Photos discovery</label><label class="flex gap-3"><input v-model="form.allow_guest_upload" type="checkbox">Allow participant uploads</label><label class="flex gap-3"><input v-model="form.watermark_enabled" type="checkbox">Apply studio watermark</label></div><div v-if="Object.keys(form.errors).length" class="rounded-xl bg-coral/10 p-4 text-sm text-coral">Please review the highlighted event details.</div><button class="btn-primary" :disabled="form.processing">{{form.processing?'Creating…':'Create event'}}</button></form></div></AppShell></template>
